CUTS=[[-143.81557558142453, -128.57733634922175, 9.0, 17.1], [-120.70214164713907, -105.46390241493633, 9.0, 17.1], [-101.23908938712658, -86.00085015492384, 9.0, 17.1], [-83.16904085261346, -67.93080162041072, 9.0, 17.1], [-62.30995218637719, -47.071712954174444, 9.0, 17.1], [-42.99556780030828, -27.757328568105535, 9.0, 17.1], [172.45843202039333, 185.25855297544365, 8.9, 19.1], [143.42235739659793, 155.61294878236015, 8.4, 12.399999999999999], [-13.318654739273297, 23.25311941801329, 11.6, 16.6]]
# Smart IoT Irrigation Controller v2 - water-drop enclosure (Fusion script)
# Units in this file: mm (converted to cm for the API). Origin = centre of the board circle.
import adsk.core, adsk.fusion, traceback, math

R_BOARD = 45.0          # board circle radius
APEX_K  = 0.8723        # cos(half-angle) of the drop tip  -> apex = R / APEX_K
TIP_R   = 2.0           # board tip fillet
GAP, WALL, FLOOR, H = 1.0, 2.0, 2.0, 23.0
BOARD_Z, BT = 7.0, 1.6
LID_T, RIM_H = 2.0, 3.0
SWITCHES = [(22.20, 25.69), (13.84, 25.78)]   # SW1, SW2 centres
LEDS = [(-16.42, 16.69), (-14.26, 30.57)]     # LED1, LED2 centres

def cm(v): return v / 10.0
def P(x, y, z=0): return adsk.core.Point3D.create(cm(x), cm(y), cm(z))

def drop(sk, off):
    """Water-drop outline offset by `off` mm from the board edge."""
    R = R_BOARD + off
    a = math.acos(APEX_K)
    apex = P(0, R / APEX_K)
    tl = P(-R * math.sin(a), R * math.cos(a))
    tr = P(R * math.sin(a), R * math.cos(a))
    L = sk.sketchCurves.sketchLines
    l1 = L.addByTwoPoints(apex, tl)
    l2 = L.addByTwoPoints(l1.startSketchPoint, tr)
    arc = sk.sketchCurves.sketchArcs.addByCenterStartSweep(P(0, 0), l1.endSketchPoint, 2 * math.pi - 2 * a)
    sk.geometricConstraints.addCoincident(arc.endSketchPoint, l2.endSketchPoint)
    r = max(0.3, TIP_R + off)
    d = 0.3 * R
    p1 = P(-d * math.sin(a) * 0.2, R / APEX_K - d * 0.2)
    p2 = P(d * math.sin(a) * 0.2, R / APEX_K - d * 0.2)
    try:
        sk.sketchCurves.sketchArcs.addFillet(l1, l1.startSketchPoint.geometry, l2, l2.startSketchPoint.geometry, cm(r))
    except:
        pass

def plane_at(comp, z):
    if abs(z) < 1e-9: return comp.xYConstructionPlane
    pi = comp.constructionPlanes.createInput()
    pi.setByOffset(comp.xYConstructionPlane, adsk.core.ValueInput.createByReal(cm(z)))
    return comp.constructionPlanes.add(pi)

def best_profile(sk, loops):
    best = None
    for p in sk.profiles:
        if p.profileLoops.count == loops:
            if best is None or p.areaProperties().area > best.areaProperties().area: best = p
    return best

def extrude(comp, prof, dist, op):
    ex = comp.features.extrudeFeatures
    inp = ex.createInput(prof, op)
    inp.setDistanceExtent(False, adsk.core.ValueInput.createByReal(cm(dist)))
    return ex.add(inp)

def tmp_box(cx, cy, cz, lx, ly, lz, ang=0.0):
    t = adsk.fusion.TemporaryBRepManager.get()
    ca, sa = math.cos(ang), math.sin(ang)
    obb = adsk.core.OrientedBoundingBox3D.create(P(cx, cy, cz), adsk.core.Vector3D.create(ca, sa, 0),
          adsk.core.Vector3D.create(-sa, ca, 0), cm(lx), cm(ly), cm(lz))
    return t.createBox(obb)

def tmp_cyl(cx, cy, z0, z1, r):
    t = adsk.fusion.TemporaryBRepManager.get()
    return t.createCylinderOrCone(P(cx, cy, z0), cm(r), P(cx, cy, z1), cm(r))

def add_bodies(comp, bodies, name):
    bf = comp.features.baseFeatures.add()
    bf.startEdit()
    out = [comp.bRepBodies.add(b, bf) for b in bodies]
    bf.finishEdit()
    bf.name = name
    return [bf.bodies.item(i) for i in range(bf.bodies.count)]

def cut(comp, target, tools):
    col = adsk.core.ObjectCollection.create()
    for t in tools: col.add(t)
    ci = comp.features.combineFeatures.createInput(target, col)
    ci.operation = adsk.fusion.FeatureOperations.CutFeatureOperation
    comp.features.combineFeatures.add(ci)

def appearance(design, body, names):
    app = adsk.core.Application.get()
    for libname in ('Fusion Appearance Library', 'Fusion 360 Appearance Library'):
        try:
            lib = app.materialLibraries.itemByName(libname)
            if not lib: continue
            for n in names:
                a = lib.appearances.itemByName(n)
                if a:
                    body.appearance = design.appearances.addByCopy(a, n + ' copy') if not design.appearances.itemByName(n + ' copy') else design.appearances.itemByName(n + ' copy')
                    return
        except: pass

def new_comp(root, name):
    occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
    occ.component.name = name
    return occ.component

def run(context):
    ui = None
    try:
        app = adsk.core.Application.get(); ui = app.userInterface
        doc = app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
        design = adsk.fusion.Design.cast(app.activeProduct)
        design.designType = adsk.fusion.DesignTypes.ParametricDesignType
        root = design.rootComponent
        NEW = adsk.fusion.FeatureOperations.NewBodyFeatureOperation
        JOIN = adsk.fusion.FeatureOperations.JoinFeatureOperation
        CUT = adsk.fusion.FeatureOperations.CutFeatureOperation

        # ---------- BASE ----------
        base = new_comp(root, 'Enclosure Base')
        sk = base.sketches.add(base.xYConstructionPlane); sk.name = 'Base outline'
        drop(sk, GAP + WALL)
        body = extrude(base, best_profile(sk, 1), H, NEW).bodies.item(0); body.name = 'Base'
        # shell from the top face
        top = [f for f in body.faces if abs(f.boundingBox.minPoint.z - cm(H)) < 1e-6 and abs(f.boundingBox.maxPoint.z - cm(H)) < 1e-6][0]
        faces = adsk.core.ObjectCollection.create(); faces.add(top)
        si = base.features.shellFeatures.createInput(faces, False)
        si.insideThickness = adsk.core.ValueInput.createByReal(cm(WALL))
        base.features.shellFeatures.add(si)
        # board ledge
        sk2 = base.sketches.add(plane_at(base, FLOOR)); sk2.name = 'Ledge'
        drop(sk2, GAP); drop(sk2, -0.6)
        extrude(base, best_profile(sk2, 2), BOARD_Z - FLOOR, JOIN)
        # wall cut-outs (terminals, DC jack, USB-C, sensor slot)
        tools = []
        for a0, a1, z0, z1 in CUTS:
            am = math.radians((a0 + a1) / 2); w = math.radians(a1 - a0) * 47.0
            tools.append(tmp_box(47.0 * math.cos(am), 47.0 * math.sin(am), (z0 + z1) / 2, 10.0, w, z1 - z0, am))
        tb = add_bodies(base, tools, 'Cut-out tools')
        cut(base, base.bRepBodies.itemByName('Base') or base.bRepBodies.item(0), tb)
        appearance(design, base.bRepBodies.item(0), ['Plastic - Matte (White)', 'Plastic - Glossy (White)'])

        # ---------- LID ----------
        lid = new_comp(root, 'Enclosure Lid')
        sk = lid.sketches.add(plane_at(lid, H)); sk.name = 'Lid outline'
        drop(sk, GAP + WALL)
        for x, y in SWITCHES:
            sk.sketchCurves.sketchLines.addCenterPointRectangle(P(x, y), P(x + 3.9, y + 3.9))
        for x, y in LEDS:
            sk.sketchCurves.sketchCircles.addByCenterRadius(P(x, y), cm(1.6))
        lb = extrude(lid, best_profile(sk, 1 + len(SWITCHES) + len(LEDS)), LID_T, NEW).bodies.item(0); lb.name = 'Lid'
        sk2 = lid.sketches.add(plane_at(lid, H)); sk2.name = 'Rim'
        drop(sk2, GAP - 0.25); drop(sk2, GAP - 1.65)
        extrude(lid, best_profile(sk2, 2), -RIM_H, JOIN)
        appearance(design, lid.bRepBodies.item(0), ['Plastic - Matte (Green)', 'Plastic - Glossy (Green)', 'Paint - Enamel Glossy (Green)'])

        # ---------- BUTTON PLUNGERS ----------
        pl = new_comp(root, 'Button Plungers')
        bodies = []
        for x, y in SWITCHES:
            sw_top = BOARD_Z + BT + 1.5 + 0.2
            bodies.append(tmp_box(x, y, sw_top + 0.6, 10, 10, 1.2))
            bodies.append(tmp_box(x, y, (sw_top + 1.2 + H + LID_T + 1.5) / 2, 6.8, 6.8, H + LID_T + 1.5 - sw_top - 1.2))
        add_bodies(pl, bodies, 'Plungers')

        # ---------- PCB + parts (reference) ----------
        pcb = new_comp(root, 'Controller PCB')
        sk = pcb.sketches.add(plane_at(pcb, BOARD_Z)); sk.name = 'Board outline'
        drop(sk, 0.0)
        pb = extrude(pcb, best_profile(sk, 1), BT, NEW).bodies.item(0); pb.name = 'PCB'
        appearance(design, pb, ['Paint - Enamel Glossy (Green)', 'Plastic - Glossy (Green)'])
        parts = []
        for d, x1, y1, x2, y2, h in COMPS:
            parts.append(tmp_box((x1 + x2) / 2, (y1 + y2) / 2, BOARD_Z + BT + h / 2, max(0.2, x2 - x1 - 0.2), max(0.2, y2 - y1 - 0.2), h))
        bb = add_bodies(pcb, parts, 'Component envelopes')
        for i, b in enumerate(bb):
            try: b.name = COMPS[i][0]
            except: pass

        app.activeViewport.fit()
        ui.messageBox('Irrigation Controller v2 enclosure built.\nComponents: Base, Lid, Button Plungers, Controller PCB.')
    except:
        if ui: ui.messageBox('Failed:\n{}'.format(traceback.format_exc()))
